settings.custom_liquid:
{% comment %}
  NOULA HOMEPAGE — SIMPLE ONE PRODUCT PAGE
  Built from the same styling system as the PDP custom liquid sections.
{% endcomment %}

<style>
  .noula-home {
    font-family: inherit;
    color: #2D241D;
    background: #FFFDF9;
  }

  .noula-home,
  .noula-home * {
    box-sizing: border-box;
    font-family: inherit;
  }

  .noula-home__section {
    padding: 38px 0;
    border-top: 1px solid #EAE1D2;
  }

  .noula-home__section:first-child {
    border-top: none;
    padding-top: 28px;
  }

  .noula-home__wrap {
    max-width: 680px;
    margin: 0 auto;
    padding: 0 16px;
  }

  .noula-home__title {
    margin: 0;
    color: #2D241D;
    font-size: clamp(31px, 8vw, 42px);
    line-height: 1.08;
    font-weight: 800;
    letter-spacing: 0;
  }

  .noula-home__hl {
    display: inline-block;
    background: #E7B4AA;
    color: #2D241D;
    padding: 1px 10px 3px;
    border-radius: 6px;
  }

  .noula-home__p {
    margin: 15px 0 0;
    color: #4A3D31;
    font-size: 15px;
    line-height: 1.58;
    letter-spacing: 0;
  }

  .noula-home__media {
    margin-top: 24px;
    border-radius: 12px;
    overflow: hidden;
    border: 1px solid #EAE1D2;
    background: #F3E8D8;
  }

  .noula-home__media img {
    width: 100%;
    height: auto;
    display: block;
  }

  .noula-home__btn {
    display: flex;
    align-items: center;
    justify-content: center;
    min-height: 50px;
    margin-top: 22px;
    border-radius: 999px;
    background: #2D241D;
    color: #FFFFFF;
    text-decoration: none;
    font-size: 14px;
    line-height: 1;
    font-weight: 800;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    padding: 16px 20px;
  }

  .noula-home__subnote {
    margin: 10px 0 0;
    color: #6B5C4F;
    font-size: 13px;
    line-height: 1.45;
    text-align: center;
  }

  .noula-home__list {
    list-style: none;
    margin: 20px 0 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 13px;
  }

  .noula-home__list li {
    display: flex;
    align-items: center;
    gap: 12px;
    color: #2D241D;
    font-size: 15px;
    font-weight: 700;
    line-height: 1.35;
  }

  .noula-home__icon {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    flex-shrink: 0;
    display: block;
  }

  .noula-home__ing-list {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-top: 24px;
  }

  .noula-home__ing-card {
    display: grid;
    grid-template-columns: 84px 1fr;
    align-items: center;
    gap: 14px;
    border: 1px solid #EAE1D2;
    border-radius: 14px;
    background: #FFFFFF;
    padding: 12px;
    box-shadow: 0 8px 24px rgba(45, 36, 29, 0.045);
  }

  .noula-home__ing-media {
    width: 84px;
    height: 84px;
    border-radius: 10px;
    background: #F3E8D8;
    border: 1px solid #EAE1D2;
    overflow: hidden;
    flex-shrink: 0;
  }

  .noula-home__ing-media img {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
  }

  .noula-home__ing-name {
    margin: 0;
    color: #2D241D;
    font-size: 18px;
    line-height: 1.18;
    font-weight: 800;
    letter-spacing: 0;
  }

  .noula-home__ing-desc {
    margin: 7px 0 0;
    color: #5F5147;
    font-size: 14px;
    line-height: 1.45;
    letter-spacing: 0;
  }

  @media screen and (min-width: 641px) {
    .noula-home__section {
      padding: 46px 0;
    }

    .noula-home__section:first-child {
      padding-top: 46px;
    }

    .noula-home__wrap {
      padding: 0 20px;
    }

    .noula-home__title {
      font-size: 42px;
      line-height: 1.08;
    }

    .noula-home__p {
      font-size: 16px;
      line-height: 1.6;
    }

    .noula-home__media {
      margin-top: 26px;
    }

    .noula-home__ing-card {
      grid-template-columns: 108px 1fr;
      gap: 18px;
      padding: 14px 18px 14px 14px;
    }

    .noula-home__ing-media {
      width: 108px;
      height: 108px;
      border-radius: 12px;
    }

    .noula-home__ing-name {
      font-size: 20px;
    }

    .noula-home__ing-desc {
      font-size: 14.5px;
    }
  }
</style>

<div class="noula-home">
  <section class="noula-home__section">
    <div class="noula-home__wrap">
      <h1 class="noula-home__title">
        Recovery that works <span class="noula-home__hl">while you sleep</span>
      </h1>

      <p class="noula-home__p">
        Noula Overnight Recovery Cream is made for the morning mirror moment: dry, dull skin that still looks tired after a full night’s sleep.
      </p>

      <p class="noula-home__p">
        Powered by Red Rice Recovery Complex™, ceramides, hyaluronic acid and Vitamin B5, it comforts and nourishes skin overnight so you wake up looking fresher, softer, and more rested.
      </p>

      <ul class="noula-home__list">
        <li>
          <img class="noula-home__icon" src="https://cdn.shopify.com/s/files/1/0809/2925/9750/files/Frame_33.png?v=1781526850" alt="" loading="lazy">
          <span>Wakes up dull, tired-looking skin</span>
        </li>

        <li>
          <img class="noula-home__icon" src="https://cdn.shopify.com/s/files/1/0809/2925/9750/files/Frame_34.png?v=1781526850" alt="" loading="lazy">
          <span>Softens the look of tired lines</span>
        </li>
      </ul>

      <a class="noula-home__btn" href="/products/overnight-recovery-cream">
        Shop Overnight Recovery Cream
      </a>

      <p class="noula-home__subnote">90-night sleep-on-it guarantee</p>

      <div class="noula-home__media">
        <img
          src="https://cdn.shopify.com/s/files/1/0809/2925/9750/files/model_916_v1.jpg?v=1781526384"
          alt="Woman applying Noula Overnight Recovery Cream"
          loading="eager"
        >
      </div>
    </div>
  </section>

  <section class="noula-home__section">
    <div class="noula-home__wrap">
      <h2 class="noula-home__title">How does it work?</h2>

      <p class="noula-home__p">
        Most night creams only sit on top of dry skin. Noula uses Red Rice Recovery Complex™ to comfort skin through the night, when your moisture barrier is most ready for support.
      </p>

      <p class="noula-home__p">
        Inspired by Korean beauty rituals, red rice extract pairs with ceramides, hyaluronic acid and Vitamin B5 to help dry, dull skin feel cushioned, hydrated and calm by morning.
      </p>
    </div>
  </section>

  <section class="noula-home__section">
    <div class="noula-home__wrap">
      <h2 class="noula-home__title">Ingredients for better-looking mornings</h2>

      <p class="noula-home__p">
        The overnight comfort your skin needs when it keeps waking up dry, dull, and tired-looking.
      </p>

      <div class="noula-home__ing-list">
        <div class="noula-home__ing-card">
          <div class="noula-home__ing-media">
            <img src="https://cdn.shopify.com/s/files/1/0809/2925/9750/files/ig_017798eba84234ca016a2ff8f929648191b9b9d8d8dd5f53fd.jpg?v=1781529292" alt="Red Rice Extract" loading="lazy">
          </div>
          <div>
            <h3 class="noula-home__ing-name">Red Rice Extract</h3>
            <p class="noula-home__ing-desc">K-beauty inspired nourishment for tired-looking skin</p>
          </div>
        </div>

        <div class="noula-home__ing-card">
          <div class="noula-home__ing-media">
            <img src="https://cdn.shopify.com/s/files/1/0809/2925/9750/files/ig_017798eba84234ca016a2ffa2c25c48191a8e775af1e4b7aee.jpg?v=1781529292" alt="Ceramides and Vitamin B5" loading="lazy">
          </div>
          <div>
            <h3 class="noula-home__ing-name">Ceramides + Vitamin B5</h3>
            <p class="noula-home__ing-desc">Comfort dry skin and support the moisture barrier</p>
          </div>
        </div>

        <div class="noula-home__ing-card">
          <div class="noula-home__ing-media">
            <img src="https://cdn.shopify.com/s/files/1/0809/2925/9750/files/ig_017798eba84234ca016a2ff9bdcdbc819191ec302ab8c2b571.jpg?v=1781529291" alt="Hyaluronic Acid" loading="lazy">
          </div>
          <div>
            <h3 class="noula-home__ing-name">Hyaluronic Acid</h3>
            <p class="noula-home__ing-desc">Draws in moisture for softer, fresher-looking skin</p>
          </div>
        </div>
      </div>
    </div>
  </section>
</div>
